import Vue from 'vue';
import { Component, Emit, Prop } from 'vue-property-decorator';

@Component({ name: 'DebugMenu' })
export default class DebugMenu extends Vue {
    @Prop({ type: String, default: '' })
    public initialHost: string;

    @Prop({ type: Boolean, default: true })
    public initialUseDebugUrl: boolean;

    public host = `${window.location.hostname}:9003`;
    public useDebugUrl = true;

    public created() {
        this.host = this.initialHost || `${window.location.hostname}:9003`;
        this.useDebugUrl = this.initialUseDebugUrl;
        this.emitHost();
        this.emitUseDebugUrl();
    }

    @Emit('onHostChange')
    public emitHost(): string {
        return this.host.trim();
    }

    @Emit('onUseDebugUrlChange')
    public emitUseDebugUrl(): boolean {
        return this.useDebugUrl;
    }
}